//! Array values: the numeric, bool and string arrays. Numeric and bool families
//! are generated by `macro_rules!`; string arrays use the multi-string pattern.

use std::ffi::c_void;

use fon::types::FonValue;

use crate::collection::{put_field, read_as};
use crate::error::{
    finish, invalid, slice_arg, to_i64, write_multi, write_sized, Failure, FonError,
};


macro_rules! put_array {
    ($name:ident, $elem:ty, $variant:ident) => {
        #[no_mangle]
        pub extern "C" fn $name(
            collection: *mut c_void,
            key: *const u8,
            key_len: i64,
            values: *const $elem,
            count: i64,
            mode: i32,
            error: *mut FonError,
        ) -> i32 {
            let result: Result<(), Failure> = unsafe {
                put_field(collection, key, key_len, mode, || -> Result<FonValue, Failure> {
                    Ok(FonValue::$variant(slice_arg(values, count)?.to_vec()))
                })
            };
            unsafe { finish(error, result) }
        }
    };
}


macro_rules! get_array {
    ($name:ident, $elem:ty, $variant:ident, $expected:literal) => {
        #[no_mangle]
        pub extern "C" fn $name(
            collection: *mut c_void,
            key: *const u8,
            key_len: i64,
            buffer: *mut $elem,
            capacity: i64,
            actual: *mut i64,
            error: *mut FonError,
        ) -> i32 {
            let result: Result<(), Failure> = unsafe {
                read_as(collection, key, key_len, $expected, |value| match value {
                    FonValue::$variant(picked) => Some(picked.as_slice()),
                    _ => None,
                })
                .and_then(|items| write_sized(items, buffer, capacity, actual))
            };
            unsafe { finish(error, result) }
        }
    };
}


put_array!(fon_collection_put_byte_array, u8, ByteArray);
put_array!(fon_collection_put_short_array, i16, ShortArray);
put_array!(fon_collection_put_int_array, i32, IntArray);
put_array!(fon_collection_put_uint_array, u32, UIntArray);
put_array!(fon_collection_put_long_array, i64, LongArray);
put_array!(fon_collection_put_ulong_array, u64, ULongArray);
put_array!(fon_collection_put_float_array, f32, FloatArray);
put_array!(fon_collection_put_double_array, f64, DoubleArray);

get_array!(fon_collection_get_byte_array, u8, ByteArray, "byte array");
get_array!(fon_collection_get_short_array, i16, ShortArray, "short array");
get_array!(fon_collection_get_int_array, i32, IntArray, "int array");
get_array!(fon_collection_get_uint_array, u32, UIntArray, "uint array");
get_array!(fon_collection_get_long_array, i64, LongArray, "long array");
get_array!(fon_collection_get_ulong_array, u64, ULongArray, "ulong array");
get_array!(fon_collection_get_float_array, f32, FloatArray, "float array");
get_array!(fon_collection_get_double_array, f64, DoubleArray, "double array");


#[no_mangle]
pub extern "C" fn fon_collection_put_bool_array(
    collection: *mut c_void,
    key: *const u8,
    key_len: i64,
    values: *const u8,
    count: i64,
    mode: i32,
    error: *mut FonError,
) -> i32 {
    let result: Result<(), Failure> = unsafe {
        put_field(collection, key, key_len, mode, || -> Result<FonValue, Failure> {
            let flags: Vec<bool> = slice_arg(values, count)?.iter().map(|&b| b != 0).collect();
            Ok(FonValue::BoolArray(flags))
        })
    };
    unsafe { finish(error, result) }
}


#[no_mangle]
pub extern "C" fn fon_collection_get_bool_array(
    collection: *mut c_void,
    key: *const u8,
    key_len: i64,
    buffer: *mut u8,
    capacity: i64,
    actual: *mut i64,
    error: *mut FonError,
) -> i32 {
    let result: Result<(), Failure> = unsafe {
        read_as(collection, key, key_len, "bool array", |value| match value {
            FonValue::BoolArray(picked) => Some(picked.as_slice()),
            _ => None,
        })
        .and_then(|flags| {
            let bytes: Vec<u8> = flags.iter().map(|&b| u8::from(b)).collect();
            write_sized(bytes.as_slice(), buffer, capacity, actual)
        })
    };
    unsafe { finish(error, result) }
}


#[no_mangle]
#[allow(clippy::too_many_arguments)]
pub extern "C" fn fon_collection_put_string_array(
    collection: *mut c_void,
    key: *const u8,
    key_len: i64,
    lengths: *const i64,
    bytes: *const u8,
    count: i64,
    mode: i32,
    error: *mut FonError,
) -> i32 {
    let result: Result<(), Failure> = unsafe {
        put_field(collection, key, key_len, mode, || -> Result<FonValue, Failure> {
            Ok(FonValue::StringArray(read_string_items(lengths, bytes, count)?))
        })
    };
    unsafe { finish(error, result) }
}


/// Splits `count` items out of `lengths` and the back-to-back `bytes` payload.
unsafe fn read_string_items(
    lengths: *const i64,
    bytes: *const u8,
    count: i64,
) -> Result<Vec<String>, Failure> {
    let lens: &[i64] = slice_arg(lengths, count)?;
    let mut sizes: Vec<usize> = Vec::with_capacity(lens.len());
    let mut total: usize = 0;
    for &len in lens {
        let size: usize = usize::try_from(len).map_err(|_| invalid("negative string length"))?;
        total = total
            .checked_add(size)
            .ok_or_else(|| invalid("string array payload too large"))?;
        sizes.push(size);
    }
    let payload: &[u8] = slice_arg(bytes, to_i64(total))?;
    let mut rest: &[u8] = payload;
    let mut items: Vec<String> = Vec::with_capacity(sizes.len());
    for size in sizes {
        let Some((head, tail)) = rest.split_at_checked(size) else {
            return Err(invalid("string array lengths exceed the payload"));
        };
        let text: &str = std::str::from_utf8(head)
            .map_err(|_| invalid("string array item is not valid UTF-8"))?;
        items.push(text.to_owned());
        rest = tail;
    }
    Ok(items)
}


#[no_mangle]
#[allow(clippy::too_many_arguments)]
pub extern "C" fn fon_collection_get_string_array(
    collection: *mut c_void,
    key: *const u8,
    key_len: i64,
    lengths: *mut i64,
    lengths_capacity: i64,
    bytes: *mut u8,
    bytes_capacity: i64,
    count: *mut i64,
    total_bytes: *mut i64,
    error: *mut FonError,
) -> i32 {
    let result: Result<(), Failure> = unsafe {
        string_array_into(
            collection,
            key,
            key_len,
            lengths,
            lengths_capacity,
            bytes,
            bytes_capacity,
            count,
            total_bytes,
        )
    };
    unsafe { finish(error, result) }
}


#[allow(clippy::too_many_arguments)]
unsafe fn string_array_into(
    collection: *mut c_void,
    key: *const u8,
    key_len: i64,
    lengths: *mut i64,
    lengths_capacity: i64,
    bytes: *mut u8,
    bytes_capacity: i64,
    count: *mut i64,
    total_bytes: *mut i64,
) -> Result<(), Failure> {
    if count.is_null() || total_bytes.is_null() {
        return Err(crate::error::invalid("count and total_bytes must not be null"));
    }
    let items: &[String] = read_as(collection, key, key_len, "string array", |value| match value {
        FonValue::StringArray(picked) => Some(picked.as_slice()),
        _ => None,
    })?;
    let parts: Vec<&[u8]> = items.iter().map(|item| item.as_bytes()).collect();
    write_multi(
        &parts,
        lengths,
        lengths_capacity,
        bytes,
        bytes_capacity,
        count,
        total_bytes,
    )?;
    Ok(())
}
